    import random
    import time

    LANGUAGE_WRAPPER = 'Square ABCD is inscribed in a circle with circumradius R. Let Γ be the circle concentric with the circumcircle of ABCD whose radius is R·sqrt({p}/{q}). There exists a unique nontrivial square EFGH whose two consecutive vertices E and F lie on segment CD and whose other two vertices G and H lie on Γ. If the ratio of the area of square EFGH to the area of square ABCD is m/n in lowest terms, compute 10n + m.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose k so that sqrt(10*kappa^2 - 1) = k is an integer in {4,5,6}
# This makes kappa^2 = (k^2 + 1)/10 and yields a rational area ratio that is nontrivial.
k = rng.choice([4, 5, 6])
p = k*k + 1  # ensures 10*(p/q) - 1 = k^2 with q=10
q = 10
return {'p': p, 'q': q, 'k': k}

    def verifier(assign):
# Validate inputs
if 'p' not in assign or 'q' not in assign:
    # missing slots
    return (False, None)  # Missing required parameters
p = assign['p']
q = assign['q']
if not isinstance(p, int) or not isinstance(q, int):
    return (False, None)  # p and q must be integers
if q <= 0:
    return (False, None)  # denominator must be positive
# Enforce the structural condition that sqrt(10*(p/q) - 1) is an integer k in {4,5,6}
# Compute K = 10*p/q - 1 as a rational; to avoid floating issues, use integer arithmetic.
num = 10 * p - q
den = q
if num % den != 0:
    return (False, None)  # K must be an integer perfect square
K = num // den
# Check perfect square
k = int(K ** 0.5)
if k * k != K:
    return (False, None)  # K must be a perfect square
# Difficulty enforcement: avoid trivial k=3 (seed) and ensure 0 < t < 1
if k < 4 or k > 6:
    return (False, None)  # restrict to nontrivial range
# Derive the smaller nontrivial side ratio t = (sqrt(10*kappa^2 - 1) - 2)/5 = (k - 2)/5
# Area ratio r = t^2 = ((k-2)^2)/25
num_r = (k - 2) ** 2
den_r = 25
# Reduce fraction
def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)
g = gcd(num_r, den_r)
m = num_r // g
n = den_r // g
# Additional sanity: ensure nontrivial (not equal to 0 or 1)
if m == 0 or m == n:
    return (False, None)  # trivial ratios are disallowed
answer = 10 * n + m
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

